 import type { Line } from "./cart";
+import { roundHalfEven } from "../money/round";

-export function total(lines: Line[]): number {
-  return lines.reduce((sum, line) => sum + line.price * line.quantity, 0);
+/** The order's total, rounded once: per-line rounding drifted by a cent (#212). */
+export function total(lines: Line[], currency = "EUR"): number {
+  const exact = lines.reduce((sum, line) => sum + line.price * line.quantity, 0);
+  return roundHalfEven(exact, currency === "JPY" ? 0 : 2);
 }

-export function tax(amount: number): number {
-  return Math.round(amount * 0.2 * 100) / 100;
+export function tax(amount: number, rate: number): number {
+  if (rate < 0 || rate > 1) throw new RangeError(`a tax rate is between 0 and 1, not ${rate}`);
+  return roundHalfEven(amount * rate, 2);
 }
