@@ -0,0 +1,9 @@
+/** Banker's rounding, to `places` decimals: ties go to the even digit. */
+export function roundHalfEven(value: number, places: number): number {
+  const m = 10 ** places;
+  const x = value * m;
+  const r = Math.round(x);
+  const tie = Math.abs(x % 1) === 0.5;
+  return (tie && r % 2 !== 0 ? r - 1 : r) / m;
+}
